contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: takes an amount to deposit and then attempts withdrawAll
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // record balances before any interaction
        uint thisBalBefore = address(this).balance;
        uint cBalBefore = address(c).balance;

        // deposit depositAmount into c from this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // balances immediately after deposit
        uint thisBalAfterDeposit = address(this).balance;
        uint cBalAfterDeposit = address(c).balance;

        // ensure deposit had expected observable effect
        // (must be a precondition-like require to make the later assert meaningful)
        require(thisBalAfterDeposit + depositAmount == thisBalBefore);
        require(cBalAfterDeposit == cBalBefore + depositAmount);

        // attempt withdrawAll and observe whether it reverted
        bool reverted;
        uint thisBalBeforeWithdraw = address(this).balance;
        uint cBalBeforeWithdraw = address(c).balance;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // single general assert describing the invariant for both cases
        assert(
            (!reverted && cBalBeforeWithdraw == address(c).balance + depositAmount && address(this).balance == thisBalBeforeWithdraw + depositAmount)
            ||
            (reverted && cBalBeforeWithdraw == address(c).balance && address(this).balance == thisBalBeforeWithdraw)
        );
    }

    receive() external payable {}
}

